import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"性能面试常考速查","description":"8 道高频题的一句话答案 + 该往哪个方向展开。详细展开见最后一列。","frontmatter":{},"headers":[],"relativePath":"面试/Performance/13-interview-qa.md","filePath":"面试/Performance/13-interview-qa.md","lastUpdated":1793113268000}'),o={name:"面试/Performance/13-interview-qa.md"};function n(i,t,l,h,s,p){return e(),r("div",null,[...t[0]||(t[0]=[d(`<h1 id="性能面试常考速查" tabindex="-1">性能面试常考速查 <a class="header-anchor" href="#性能面试常考速查" aria-label="Permalink to &quot;性能面试常考速查&quot;">​</a></h1><blockquote><p>8 道高频题的一句话答案 + 该往哪个方向展开。详细展开见最后一列。</p></blockquote><h2 id="一、核心指标" tabindex="-1">一、核心指标 <a class="header-anchor" href="#一、核心指标" aria-label="Permalink to &quot;一、核心指标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题目</th><th>一句话答案</th><th>展开</th></tr></thead><tbody><tr><td>Web Vitals 三大指标?</td><td>LCP(最大内容渲染,看加载)、INP(交互到下次绘制,看响应)、CLS(累积布局偏移,看稳定),三者按 P75 分位看</td><td><a href="/performance/26-web-vitals-deep">→</a></td></tr><tr><td>LCP 为什么慢?</td><td>四段:TTFB(服务端慢)、资源下载慢(没走 CDN / 没压缩)、资源本身大(图/JS)、渲染被阻塞(关键 CSS/JS)。先量再改</td><td><a href="/performance/2-core-vitals">→</a></td></tr><tr><td>CLS 怎么消除?</td><td>根因几乎都是「尺寸没预留」:图片/视频给宽高、字体用 <code>font-display: swap</code>、动态内容预留容器、弹窗不用绝对定位硬插</td><td><a href="/performance/2-core-vitals">→</a></td></tr><tr><td>INP 怎么优化?</td><td>拆长任务(&gt;50ms)、减少主线程 JS、第三方脚本延后到交互后、必要时 <code>scheduler.yield()</code> 让出主线程</td><td><a href="/performance/26-web-vitals-deep">→</a></td></tr></tbody></table><h2 id="二、加载与首屏" tabindex="-1">二、加载与首屏 <a class="header-anchor" href="#二、加载与首屏" aria-label="Permalink to &quot;二、加载与首屏&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题目</th><th>一句话答案</th><th>展开</th></tr></thead><tbody><tr><td>首屏 4s 怎么优化到 1s?</td><td>先分清用户等的是「数据」还是「代码」:数据慢查 TTFB 和接口,代码多就减关键资源 + 关键 CSS 内联 + Streaming SSR + 骨架屏</td><td><a href="/performance/8-first-screen">→</a></td></tr><tr><td>静态资源缓存策略?</td><td>带 hash 的文件 <code>max-age=31536000, immutable</code> 长缓存;HTML 不缓存或 <code>no-cache</code>,保证发版能拿到新版本</td><td><a href="/performance/6-network-optimization">→</a></td></tr><tr><td>preload / prefetch 区别?</td><td>preload 是「现在就要用」提前拉,prefetch 是「可能要用」空闲拉;滥用 preload 抢带宽反而更慢</td><td><a href="/performance/6-network-optimization">→</a></td></tr></tbody></table><h2 id="三、运行时" tabindex="-1">三、运行时 <a class="header-anchor" href="#三、运行时" aria-label="Permalink to &quot;三、运行时&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题目</th><th>一句话答案</th><th>展开</th></tr></thead><tbody><tr><td>长列表怎么优化?</td><td>虚拟列表:只渲染可视区 + 缓冲区,DOM 从 1 万降到几十。核心是可视区起止索引 + 滚动偏移量</td><td><a href="/performance/19-long-list">→</a></td></tr><tr><td>内存泄漏怎么排查?</td><td>Chrome DevTools → Memory → 两次 Heap Snapshot 做差分,看对象数是否持续增长;泄漏常见于没解绑的事件/定时器、闭包持有大对象</td><td><a href="/performance/20-memory">→</a></td></tr><tr><td>Web Worker 用在哪?</td><td>主线程单次任务 &gt; 50ms 且可切分时:大数据排序、复杂 JSON 解析、加解密、大量正则。轻任务用 Worker 反而更慢</td><td><a href="/performance/27-web-worker">→</a></td></tr></tbody></table><h2 id="四、构建" tabindex="-1">四、构建 <a class="header-anchor" href="#四、构建" aria-label="Permalink to &quot;四、构建&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题目</th><th>一句话答案</th><th>展开</th></tr></thead><tbody><tr><td>Vite 为什么比 Webpack 快?</td><td>dev 用原生 ESM 按需编译(不打包),依赖用 esbuild 预构建;prod 用 Rollup。冷启动和 HMR 是数量级差异</td><td><a href="/工程化/vite/">→</a></td></tr><tr><td>Tree Shaking 原理?</td><td>基于 ES Module 静态分析,标记未引用的导出并删除;CommonJS 无法静态分析,所以摇树失效</td><td><a href="/performance/5-webpack-optimization">→</a></td></tr><tr><td>包体积怎么优化?</td><td>先用可视化工具定位大包 → 路由级动态 import 分包 → splitChunks 抽公共依赖 → 换轻量库(如 moment → dayjs)→ 压缩</td><td><a href="/performance/5-webpack-optimization">→</a></td></tr></tbody></table><h2 id="五、推荐回答结构" tabindex="-1">五、推荐回答结构 <a class="header-anchor" href="#五、推荐回答结构" aria-label="Permalink to &quot;五、推荐回答结构&quot;">​</a></h2><p>性能题的答案不要从「优化手段清单」开始讲,按这个顺序:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 定位   —— 怎么测出来的?(Lighthouse / DevTools / RUM,给出数字)</span></span>
<span class="line"><span>2. 判断   —— 瓶颈在服务端还是客户端?(TTFB vs 资源 vs 渲染)</span></span>
<span class="line"><span>3. 动作   —— 只讲最关键的一两项,不要罗列十条</span></span>
<span class="line"><span>4. 验证   —— 改完怎么确认?(同口径复测 + 上线后 RUM 对比)</span></span>
<span class="line"><span>5. 复盘   —— 如果重来会怎么做(体现取舍)</span></span></code></pre></div><p>面试官真正想听的是 <strong>1 和 5</strong>,而不是 3。</p><h2 id="📚-延伸阅读" tabindex="-1">📚 延伸阅读 <a class="header-anchor" href="#📚-延伸阅读" aria-label="Permalink to &quot;📚 延伸阅读&quot;">​</a></h2><ul><li><a href="/performance/7-checklist">性能优化清单(发布前必看)</a></li><li><a href="/performance/21-methodology">性能优化方法论:Measure → Profile → Optimize → Verify</a></li><li><a href="/performance/24-real-project">真实项目复盘:Webpack → Vite 迁移</a></li><li><a href="/前端/monitoring/">前端监控与稳定性专题</a></li></ul><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>这张表是<strong>速查</strong>:一句话答案够应付快问,深挖靠「展开」列指向的专题页。</li><li>回答性能题的重心在定位和复盘,不在优化手段的数量。</li><li>每个指标都要能说出「怎么看」和「怎么改」,才算真的懂。</li></ul>`,18)])])}const f=a(o,[["render",n]]);export{m as __pageData,f as default};
